<section class="container narrow section-top"><?php ff_heading('order_details','Every transaction on this project is simulated.'); ?><div class="panel"><div class="badge-row"><?php ff_badge($order['status']??'pending'); ?></div><h2><?=e($order['title_snapshot']??$order['title']??t('demo_order'))?></h2><dl class="detail-facts"><div><dt><?=e(t('order_reference'))?></dt><dd><?=e($order['reference']??$order['id'])?></dd></div><div><dt><?=e(t('date'))?></dt><dd><?=e(local_time($order['created_at']??''))?></dd></div><div><dt><?=e(t('total'))?></dt><dd><?=e(money($order['total']??0))?></dd></div><div><dt><?=e(t('payment_method'))?></dt><dd><?=e(t($order['method']??$order['payment_method']??'demo'))?></dd></div></dl><?php $orderStatus=$order['status']??'pending'; ?><div class="notice compact"><p><?=e(t(in_array($orderStatus,['paid','success','completed'])?'Your simulated payment succeeded. Your demo pass is available in your member space.':(in_array($orderStatus,['failed','failure'])?'This simulated payment failed. No demo membership was activated.':'Your demo order is pending. An administrator must confirm payment before a demo membership is activated.')))?></p></div><div class="button-row"><a class="button" href="<?=e(url(in_array($orderStatus,['paid','success','completed'])?'passes':'orders'))?>"><?=e(t(in_array($orderStatus,['paid','success','completed'])?'my_passes':'my_orders'))?> <?=ff_icon()?></a><button class="button secondary" type="button" data-print><?=e(t('print_confirmation'))?></button></div></div></section>
